// Source list. Edit here or load from config/sources.yml (mounted).
// Each item becomes one call to the playwright-service /scrape endpoint.
const sources = [
  { type: 'greenhouse', board: 'gitlab' },
  { type: 'greenhouse', board: 'stripe' },
  { type: 'lever', company: 'netflix' }
  // { type: 'genericCareers', url: 'https://example.com/careers', company_name: 'Example' }
];
return sources.map((s) => ({ json: s }));

// Flatten jobs from all sources into one parameterized INSERT each.
// content_hash is computed in SQL (md5) for exact-duplicate suppression.
function esc(v){ if(v===null||v===undefined) return 'NULL'; return `'${String(v).replace(/'/g,"''")}'`; }
function boolSql(v){ return (v===null||v===undefined) ? 'NULL' : (v ? 'true':'false'); }
const out=[];
for (const it of $input.all()) {
  const jobs = it.json.jobs || [];
  for (const j of jobs) {
    const raw = JSON.stringify(j).replace(/'/g, "''");
    const hashExpr = `md5(lower(coalesce(${esc(j.title)},''))||'|'||lower(coalesce(${esc(j.company_name)},''))||'|'||left(lower(coalesce(${esc(j.description)},'')),500))`;
    const query = `INSERT INTO app.jobs (source, source_job_id, title, company_name, location, remote, url, description, raw, content_hash, status)\nVALUES (${esc(j.source)}, ${esc(j.source_job_id)}, ${esc(j.title)}, ${esc(j.company_name)}, ${esc(j.location)}, ${boolSql(j.remote)}, ${esc(j.url)}, ${esc(j.description)}, '${raw}'::jsonb, ${hashExpr}, 'discovered')\nON CONFLICT (content_hash) DO NOTHING;`;
    out.push({ json: { query, title: j.title, company: j.company_name } });
  }
}
return out.length ? out : [{ json: { query: 'SELECT 1;', title: null, company: null } }];
